// Auto-generated ambient module declarations for static assets
// Prevents TypeScript errors when importing styles or images in .tsx files

declare module '*.css';
declare module '*.scss';

declare module '*.module.css' {
  const classes: { [className: string]: string };
  export default classes;
}

declare module '*.svg' {
  const src: string;
  export default src;
}

declare module '*.png';
declare module '*.jpg';
declare module '*.jpeg';
declare module '*.webp';
